// server/lib/auth.ts
import fs from "node:fs";
import path from "node:path";
import { createRemoteJWKSet, jwtVerify } from "jose";
var FIREBASE_JWKS = createRemoteJWKSet(
  new URL("https://www.googleapis.com/service_accounts/v1/jwk/securetoken@system.gserviceaccount.com")
);
var cachedProjectId = null;
function getFirebaseProjectId() {
  if (cachedProjectId) return cachedProjectId;
  if (process.env.FIREBASE_PROJECT_ID) {
    cachedProjectId = process.env.FIREBASE_PROJECT_ID;
    return cachedProjectId;
  }
  const configPath = path.resolve(process.cwd(), "firebase-applet-config.json");
  if (fs.existsSync(configPath)) {
    const raw = JSON.parse(fs.readFileSync(configPath, "utf8"));
    if (raw.projectId) {
      cachedProjectId = raw.projectId;
      return cachedProjectId;
    }
  }
  cachedProjectId = "commanding-obelisk-5vc14";
  return cachedProjectId;
}
var BOOTSTRAP_SUPER_ADMIN_EMAIL = (process.env.BOOTSTRAP_SUPER_ADMIN_EMAIL || "onlineguard515@gmail.com").toLowerCase();
async function verifyFirebaseIdToken(authHeader) {
  if (!authHeader || !authHeader.startsWith("Bearer ")) {
    throw new Error("MISSING_AUTH_TOKEN");
  }
  const token = authHeader.slice("Bearer ".length).trim();
  if (!token) {
    throw new Error("MISSING_AUTH_TOKEN");
  }
  const projectId = getFirebaseProjectId();
  const { payload } = await jwtVerify(token, FIREBASE_JWKS, {
    issuer: `https://securetoken.google.com/${projectId}`,
    audience: projectId
  });
  const uid = typeof payload.sub === "string" ? payload.sub : "";
  const email = typeof payload.email === "string" ? payload.email : "";
  const emailVerified = payload.email_verified === true;
  const name = typeof payload.name === "string" ? payload.name : void 0;
  if (!uid) {
    throw new Error("INVALID_AUTH_TOKEN");
  }
  return { uid, email, emailVerified, name };
}

// server/lib/gemini.ts
import { GoogleGenAI } from "@google/genai";
var cachedClient = null;
var KAR_GEMINI_MODEL = process.env.GEMINI_MODEL || "gemini-3.5-flash-lite";
function getGeminiClient() {
  const apiKey = process.env.GEMINI_API_KEY;
  if (!apiKey || apiKey === "MY_GEMINI_API_KEY") {
    throw new Error("GEMINI_UNAVAILABLE");
  }
  if (!cachedClient) {
    cachedClient = new GoogleGenAI({
      apiKey,
      httpOptions: {
        headers: {
          "User-Agent": "aistudio-build"
        }
      }
    });
  }
  return cachedClient;
}

