        intro: '\u0633\u06B5\u0627\u0648 \u0644\u06D5 \u0626\u06D5\u0646\u062F\u0627\u0632\u06CC\u0627\u0631\u06D5 \u0646\u06D5\u062E\u0634\u06D5\u06A9\u06CE\u0634\u06D5\u06A9\u0627\u0646! \u062A\u0627 \u0626\u06CE\u0633\u062A\u0627 \u0646\u06D5\u062E\u0634\u06D5\u06CC \u062E\u0627\u0646\u0648\u0648\u062A \u0628\u06CC\u0646\u06CC\u0648\u06D5 \u0644\u06D5\u0633\u06D5\u0631 \u067E\u06D5\u0695\u06D5 \u06A9\u06D5 \u0646\u0648\u0633\u0631\u0627\u0648\u06D5: "\u0626\u06CE\u0631\u06D5 \u0647\u06C6\u06B5\u06D5\u060C \u0626\u06CE\u0631\u06D5 \u0698\u0648\u0648\u0631\u06CC \u0646\u0648\u0648\u0633\u062A\u0646\u06D5\u060C \u0626\u06CE\u0631\u06D5 \u0628\u0627\u06B5\u06A9\u06C6\u0646\u06D5"\u061F \u0644\u06D5 CSS Grid \u062F\u0627 \u062F\u06D5\u062A\u0648\u0627\u0646\u06CC\u062A \u0628\u06D5 \u0648\u0634\u06D5\u06CC \u0633\u0627\u062F\u06D5 \u0646\u06D5\u062E\u0634\u06D5\u06CC \u062A\u06D5\u0648\u0627\u0648\u06CC \u0645\u0627\u06B5\u067E\u06D5\u0695\u06D5\u06A9\u06D5\u062A \u0628\u0646\u06D5\u062E\u0634\u06CE\u0646\u06CC\u062A \u0628\u06D5\u0628\u06CE \u0698\u0645\u0627\u0631\u06D5 \u0648 \u062D\u06CC\u0633\u0627\u0628\u0627\u062A\u06CC \u0626\u0627\u06B5\u06C6\u0632!',
