        intro: '\u0633\u06B5\u0627\u0648 \u0644\u06D5 \u0695\u0627\u0632\u06CE\u0646\u06D5\u0631\u0627\u0646\u06CC \u0634\u0627\u0634\u06D5! \u0644\u06D5 \u0626\u0627\u0645\u0631\u0627\u0632\u06D5\u06A9\u0627\u0646\u06CC \u062A\u0631\u062F\u0627 \u062F\u06D5\u0628\u0648\u0648 \u062F\u06D5\u06CC\u0627\u0646 \u067E\u0627\u06A9\u06CE\u062C\u06CC \u0648\u06D5\u06A9 css-loader \u0648 style-loader \u062F\u0627\u0628\u0628\u06D5\u0632\u06CE\u0646\u06CC\u062A \u062A\u0627 \u0628\u062A\u0648\u0627\u0646\u06CC\u062A \u0641\u0627\u06CC\u0644\u06CC CSS \u0628\u0627\u0646\u06AF \u0628\u06A9\u06D5\u06CC\u062A. \u0628\u06D5\u06B5\u0627\u0645 \u0644\u06D5 Vite \u062F\u0627 \u067E\u0634\u062A\u06AF\u06CC\u0631\u06CC \u062A\u06D5\u0648\u0627\u0648\u06CC CSS \u0644\u06D5 \u0633\u06D5\u0631\u06D5\u062A\u0627\u0648\u06D5 \u0626\u0627\u0645\u0627\u062F\u06D5\u06CC\u06D5! \u062A\u06D5\u0646\u0647\u0627 \u0628\u06D5 \u06CC\u06D5\u06A9 \u062F\u06CE\u0695\u06CC import "./style.css" \u062A\u06D5\u0648\u0627\u0648\u06CC \u0633\u062A\u0627\u06CC\u0644\u06D5\u06A9\u0627\u0646\u062A \u062F\u06D5\u0686\u0646\u06D5 \u0646\u0627\u0648 \u0645\u0627\u06B5\u067E\u06D5\u0695\u06D5\u06A9\u06D5.',
