        intro: '\u0633\u06B5\u0627\u0648 \u0644\u06D5 \u062F\u06D5\u0633\u062A\u0646\u06CC\u0634\u0627\u0646\u06A9\u0627\u0631\u0627\u0646\u06CC \u062F\u0627\u062A\u0627! \u06A9\u0627\u062A\u06CE\u06A9 \u0628\u06C6\u0631\u06CC \u0626\u0627\u0648 \u062F\u06D5\u0628\u06D5\u0633\u062A\u06CC\u062A\u060C \u062A\u06D5\u0646\u0647\u0627 \u0626\u0627\u0648\u06CC \u062A\u06CE\u062F\u06D5\u0686\u06CE\u062A\u061B \u0646\u0627\u062A\u0648\u0627\u0646\u06CC\u062A \u062F\u0627\u0631 \u06CC\u0627\u0646 \u0628\u06D5\u0631\u062F\u06CC \u062A\u06CE\u0628\u06A9\u06D5\u06CC\u062A \u0686\u0648\u0646\u06A9\u06D5 \u0628\u06C6\u0631\u06CC\u06CC\u06D5\u06A9\u06D5 \u062F\u06D5\u06AF\u06CC\u0631\u06CE\u062A. \u0644\u06D5 TypeScript \u062F\u0627 \u06A9\u0627\u062A\u06CE\u06A9 \u062F\u06D5\u06B5\u06CE\u06CC\u062A: "\u0626\u06D5\u0645 \u0633\u0646\u062F\u0648\u0642\u06D5 \u062A\u06D5\u0646\u0647\u0627 \u0628\u06C6 \u0698\u0645\u0627\u0631\u06D5\u06CC\u06D5"\u060C \u0626\u06D5\u06AF\u06D5\u0631 \u06A9\u06D5\u0633\u06CE\u06A9 \u062F\u06D5\u0642\u06CC \u062A\u06CE\u0628\u06A9\u0627\u062A \u062F\u06D5\u0633\u062A\u0628\u06D5\u062C\u06CE \u06A9\u06C6\u0645\u067E\u06CC\u0648\u062A\u06D5\u0631 \u0695\u06CE\u06AF\u0631\u06CC \u0644\u06CE\u062F\u06D5\u06A9\u0627\u062A!',
