        intro: '\u0633\u06B5\u0627\u0648 \u0644\u06D5 \u0647\u06C6\u0634\u06CC\u0627\u0631\u0627\u0646\u06CC \u0648\u06CE\u0628! \u0628\u06D5\u0646\u0627\u0648\u0628\u0627\u0646\u06AF\u062A\u0631\u06CC\u0646 \u0647\u06D5\u06B5\u06D5 \u0644\u06D5 \u062A\u06D5\u0648\u0627\u0648\u06CC \u0645\u06CE\u0698\u0648\u0648\u06CC \u067E\u0631\u06C6\u06AF\u0631\u0627\u0645\u0633\u0627\u0632\u06CC\u062F\u0627 \u0686\u06CC\u06CC\u06D5\u061F \u0626\u06D5\u0648\u06D5\u06CC\u06D5 \u06A9\u06D5 \u062F\u06D5\u06B5\u06CE\u062A: "Cannot read properties of undefined"! \u0632\u06C6\u0631\u0628\u06D5\u06CC \u06A9\u0627\u062A \u0644\u0627\u067E\u06D5\u0695\u06D5 \u0644\u06D5\u0628\u06D5\u0631 \u0626\u06D5\u0648\u06D5 \u062A\u06CE\u06A9\u062F\u06D5\u0686\u06CE\u062A \u06A9\u06D5 \u062F\u06D5\u0633\u062A\u06A9\u0627\u0631\u06CC \u0634\u062A\u06CE\u06A9 \u062F\u06D5\u06A9\u06D5\u06CC\u062A \u06A9\u06D5 \u0647\u06CE\u0634\u062A\u0627 \u0646\u06D5\u06AF\u06D5\u06CC\u0634\u062A\u0648\u0648\u06D5\u062A\u06D5 \u0633\u06D5\u0631 \u0634\u0627\u0634\u06D5\u06A9\u06D5. \u0628\u06D5\u06B5\u0627\u0645 \u0628\u06D5 \u0647\u06CE\u0645\u0627\u06CC \u067E\u0631\u0633\u06CC\u0627\u0631\u06CC \u0646\u06D5\u0631\u0645 (?) \u062F\u06D5\u062A\u0648\u0627\u0646\u06CC\u062A \u0644\u06D5\u0645 \u06A9\u0627\u0631\u06D5\u0633\u0627\u062A\u06D5 \u0695\u0632\u06AF\u0627\u0631\u062A \u0628\u06CE\u062A!',
