        commonMistakes: ["\u062C\u06CE\u0647\u06CE\u0634\u062A\u0646\u06CC \u0641\u06D5\u0646\u06A9\u0634\u0646\u06CC async \u0628\u06D5\u0628\u06CE \u062F\u06CC\u0627\u0631\u06CC\u06A9\u0631\u062F\u0646\u06CC \u062C\u06C6\u0631\u06CC \u06AF\u06D5\u0695\u0627\u0648\u06D5\u06CC Promise.", "\u0628\u0627\u0648\u06D5\u0695\u06A9\u0631\u062F\u0646\u06CC \u06A9\u0648\u06CE\u0631\u0627\u0646\u06D5 \u0628\u06D5\u0648\u06D5\u06CC \u06A9\u06D5 \u0633\u06CE\u0631\u06A4\u06D5\u0631 \u0647\u06D5\u0645\u06CC\u0634\u06D5 \u0661\u0660\u0660\u066A \u0628\u06D5\u067E\u06CE\u06CC \u0642\u0627\u06B5\u0628\u06D5\u06A9\u06D5 \u062F\u0627\u062A\u0627\u06A9\u06D5\u062A \u067E\u06CE\u062F\u06D5\u062F\u0627\u062A \u0628\u06D5\u0628\u06CE \u067E\u0634\u06A9\u0646\u06CC\u0646\u06CC \u0647\u06D5\u06B5\u06D5."],
