        intro: '\u0633\u06B5\u0627\u0648 \u0644\u06D5 \u0641\u06D5\u0631\u0647\u06D5\u0646\u06AF\u0646\u0648\u0648\u0633\u0627\u0646! \u06A9\u0627\u062A\u06CE\u06A9 \u0641\u06D5\u0631\u0647\u06D5\u0646\u06AF\u06CC \u06A9\u0648\u0631\u062F\u06CC-\u0626\u06CC\u0646\u06AF\u0644\u06CC\u0632\u06CC \u062F\u06D5\u06A9\u06D5\u06CC\u062A\u06D5\u0648\u06D5\u060C \u0628\u06D5\u062F\u0648\u0627\u06CC \u0648\u0634\u06D5\u06CC "\u06A9\u062A\u06CE\u0628"\u062F\u0627 \u062F\u06D5\u06AF\u06D5\u0695\u06CE\u06CC\u062A \u0648 \u06CC\u06D5\u06A9\u0633\u06D5\u0631 \u0645\u0627\u0646\u0627\u06A9\u06D5\u06CC \u062F\u06D5\u062F\u06C6\u0632\u06CC\u062A\u06D5\u0648\u06D5 \u06A9\u06D5 "Book" \u06D5. \u0644\u06D5 \u0632\u0645\u0627\u0646\u06CC \u067E\u0627\u06CC\u0633\u0646 \u0626\u06D5\u0645 \u062C\u06C6\u0631\u06D5 \u0633\u0646\u062F\u0648\u0642\u06D5 \u0628\u06D5\u0647\u06CE\u0632\u06D5 \u067E\u06CE\u06CC \u062F\u06D5\u0648\u062A\u0631\u06CE\u062A Dictionary (\u06A9\u0648\u0631\u062A\u06A9\u0631\u0627\u0648\u06D5\u06CC dict)\u060C \u06A9\u06D5 \u0632\u0627\u0646\u06CC\u0627\u0631\u06CC\u06CC\u06D5\u06A9\u0627\u0646 \u0628\u06D5 \u06A9\u0644\u06CC\u0644 \u0648 \u0646\u0631\u062E \u0644\u06D5 \u0628\u0627\u0648\u06D5\u0634 \u062F\u06D5\u06AF\u0631\u06CE\u062A!',
