        explanation: '\u{1F393} \u0634\u06CC\u06A9\u0631\u062F\u0646\u06D5\u0648\u06D5\u06CC \u0641\u06D5\u0631\u0647\u06D5\u0646\u06AF\u06CC \u062F\u0627\u062A\u0627 (ELI5):\n\n\u0661. \u062F\u0631\u0648\u0633\u062A\u06A9\u0631\u062F\u0646 \u0628\u06D5 \u06A9\u06D5\u0648\u0627\u0646\u06D5\u06CC \u06A9\u0631\u0698 { ... }:\n  student = {\n    "name": "\u0695\u06D5\u0648\u06D5\u0646\u062F",\n    "age": 21,\n    "grade": "A",\n    "passed": True\n  }\n\n\u0662. \u062E\u0648\u06CE\u0646\u062F\u0646\u06D5\u0648\u06D5 \u0628\u06D5 \u06A9\u0644\u06CC\u0644:\n\u2022 student["name"] \u062F\u06D5\u0628\u06CE\u062A\u06D5 "\u0695\u06D5\u0648\u06D5\u0646\u062F".\n\n\u0663. \u0695\u06CE\u06AF\u0627\u06CC \u067E\u0627\u0631\u06CE\u0632\u0631\u0627\u0648 \u0628\u06D5 .get():\n\u2022 \u0626\u06D5\u06AF\u06D5\u0631 \u0628\u0646\u0648\u0648\u0633\u06CC\u062A student["city"] \u0644\u06D5\u0648\u0627\u0646\u06D5\u06CC\u06D5 \u0647\u06D5\u06B5\u06D5 \u0628\u062F\u0627\u062A \u0626\u06D5\u06AF\u06D5\u0631 \u0634\u0627\u0631 \u0628\u0648\u0648\u0646\u06CC \u0646\u06D5\u0628\u06CE\u062A\u061B \u0628\u06D5\u06B5\u0627\u0645 \u0626\u06D5\u06AF\u06D5\u0631 \u0628\u0646\u0648\u0648\u0633\u06CC\u062A student.get("city", "\u0646\u0627\u062F\u06CC\u0627\u0631") \u0626\u06D5\u06AF\u06D5\u0631 \u0646\u06D5\u0628\u0648\u0648 \u0632\u06C6\u0631 \u0628\u06D5 \u0647\u06CE\u0645\u0646\u06CC \u0648\u0634\u06D5\u06CC "\u0646\u0627\u062F\u06CC\u0627\u0631" \u062F\u06D5\u06AF\u06D5\u0695\u06CE\u0646\u06CE\u062A\u06D5\u0648\u06D5 \u0628\u06D5\u0628\u06CE \u062F\u0627\u0695\u0645\u0627\u0646\u06CC \u0628\u06D5\u0631\u0646\u0627\u0645\u06D5\u06A9\u06D5\u062A!\n\n\u0664. \u0632\u06CC\u0627\u062F\u06A9\u0631\u062F\u0646 \u0648 \u062F\u06D5\u0633\u062A\u06A9\u0627\u0631\u06CC\u06A9\u0631\u062F\u0646:\n  student["city"] = "\u06A9\u06D5\u0631\u06A9\u0648\u0648\u06A9"\n\u2022 \u0628\u06D5 \u06CC\u06D5\u06A9 \u062F\u06CE\u0695 \u062E\u0627\u0646\u06D5\u06CC\u06D5\u06A9\u06CC \u0646\u0648\u06CE \u0628\u06C6 \u0641\u06D5\u0631\u0647\u06D5\u0646\u06AF\u06D5\u06A9\u06D5 \u0632\u06CC\u0627\u062F \u062F\u06D5\u0628\u06CE\u062A.',
        syntaxNotes: "\u0626\u0627\u0645\u06C6\u0698\u06AF\u0627\u0631\u06CC \u0632\u06CE\u0695\u06CC\u0646\u06CC \u0645\u0627\u0645\u06C6\u0633\u062A\u0627: \u0647\u06D5\u0645\u06CC\u0634\u06D5 \u0641\u06D5\u0631\u0645\u0627\u0646\u06CC .get() \u0628\u06D5\u06A9\u0627\u0631\u0628\u0647\u06CE\u0646\u06D5 \u0628\u06C6 \u062E\u0648\u06CE\u0646\u062F\u0646\u06D5\u0648\u06D5\u06CC \u0626\u06D5\u0648 \u06A9\u0644\u06CC\u0644\u0627\u0646\u06D5\u06CC \u06A9\u06D5 \u062F\u06B5\u0646\u06CC\u0627 \u0646\u06CC\u062A \u0626\u0627\u06CC\u0627 \u0644\u06D5\u0646\u0627\u0648 \u0641\u06D5\u0631\u0647\u06D5\u0646\u06AF\u06D5\u06A9\u06D5\u062F\u0627 \u0647\u06D5\u0646 \u06CC\u0627\u0646 \u0646\u0627.",
